  body { font-family: sans-serif; background: #fff6e6; padding: 20px; }
  h1 { color: #6c47ff; font-size: 40px; }
  .card { background: white; border: 3px solid black; border-radius: 16px; padding: 16px; box-shadow: 5px 5px 0 black; }
</style>

