INSERT OR IGNORE INTO lessons (track_id, slug, title, summary, sort, is_free, xp, kind, minutes, video_url, content_md, quiz_text, is_published, updated_at) VALUES ((SELECT id FROM tracks WHERE slug = 'tiny-coders'), 'tiny-pattern-party', 'Pattern Party', 'Spot what comes next. Patterns are a secret superpower of coders.', 2, 1, 15, 'lesson', 6, NULL, '## Patterns are everywhere! 🎨

A **pattern** is something that repeats again and again.

🍎 🍌 🍎 🍌 🍎 🍌

Can you see it? Apple, banana, apple, banana…

> 👪 **Grown-up tip:** clap the pattern together: *clap, stomp, clap, stomp*. Then ask "what comes next?"

## What comes next?

Look at each line and guess. Then tap to check!

🔴 🔵 🔴 🔵 🔴 ❓

```reveal
What comes next?
🔵 **Blue!** The pattern is red, blue, red, blue.
```

🐱 🐶 🐶 🐱 🐶 🐶 🐱 ❓

```reveal
What comes next?
🐶 **Dog!** The pattern is cat, dog, dog… then it starts again.
```

⭐ ⭐ 🌙 ⭐ ⭐ 🌙 ⭐ ❓

```reveal
What comes next?
⭐ **Star!** Two stars, one moon, again and again.
```

## Why do coders love patterns?

When a computer sees a pattern, it can **repeat** it super fast. Coders spot patterns so they can write fewer instructions. Clever!

## Make your own 🖍️

Grab some crayons, blocks or toys and make your own pattern. Can your grown-up guess what comes next?
', 'Q: What comes next? 🍎 🍌 🍎 🍌 🍎 ❓
- 🍎
* 🍌
- 🍇
> The pattern is apple, banana, so after 🍎 comes 🍌!

Q: A pattern is something that…
* repeats again and again
- is always red
- never happens
> Patterns repeat. Computers are great at repeating things!', 1, 1795551414802);
INSERT OR IGNORE INTO lessons (track_id, slug, title, summary, sort, is_free, xp, kind, minutes, video_url, content_md, quiz_text, is_published, updated_at) VALUES ((SELECT id FROM tracks WHERE slug = 'tiny-coders'), 'tiny-turns', 'Up, Down, Left, Right', 'Robo needs to turn corners. Can you find the path?', 3, 1, 20, 'game', 6, NULL, '## Robo meets a wall 🧱

