INSERT OR IGNORE INTO lessons (track_id, slug, title, summary, sort, is_free, xp, kind, minutes, video_url, content_md, quiz_text, is_published, updated_at) VALUES ((SELECT id FROM tracks WHERE slug = 'tiny-coders'), 'tiny-first-next-last', 'First, Next, Last', 'Order matters! Put steps in the right order and collect the gem.', 4, 0, 25, 'game', 8, NULL, '## Order matters! 🪥

What happens if you put your socks on **after** your shoes? 🧦👟 Silly!

